using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates decoding at resolutions that are not multiples of the superblock size on two real
/// four-frame aomenc clips (100x76 and 98x66, the latter with an odd chroma width): partitions signal
/// at the frame edges, blocks and transform blocks overhang into the superblock-aligned plane area,
/// chroma-from-luma reads overhanging luma, motion compensation replicates edges at the visible size and
/// the post filters run to the visible bounds. Every decoded frame's cropped planes must be exactly
/// equal to dav1d's decoded output.
/// </summary>
public class Av1ArbitraryResolutionDecodeTests
{
    private const string Clip100x76IvfBase64 =
        "";

    private const string Clip98x66IvfBase64 =
        "";

    private static readonly string[] Dav1d100x76LumaBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1d100x76UBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1d100x76VBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1d98x66LumaBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1d98x66UBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1d98x66VBase64 = [
        "",
        "",
        "",
        ""
    ];

    [Fact]
    public void DecodeAllFrames_100x76_MatchDav1dExactly()
        => DecodeAndCompare(Clip100x76IvfBase64, Dav1d100x76LumaBase64, Dav1d100x76UBase64, Dav1d100x76VBase64);

    [Fact]
    public void DecodeAllFrames_98x66_MatchDav1dExactly()
        => DecodeAndCompare(Clip98x66IvfBase64, Dav1d98x66LumaBase64, Dav1d98x66UBase64, Dav1d98x66VBase64);

    private static void DecodeAndCompare(string ivfBase64, string[] lumaBase64, string[] uBase64, string[] vBase64)
    {
        using MemoryStream stream = new(Convert.FromBase64String(ivfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(4, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(lumaBase64[i]), Crop(frames[i].Luma));
            Assert.Equal(Convert.FromBase64String(uBase64[i]), Crop(frames[i].ChromaU));
            Assert.Equal(Convert.FromBase64String(vBase64[i]), Crop(frames[i].ChromaV));
        }
    }

    private static byte[] Crop(Av1Plane plane)
    {
        byte[] result = new byte[plane.CropWidth * plane.CropHeight];
        for (int y = 0; y < plane.CropHeight; y++)
        {
            plane.Samples.AsSpan(y * plane.Width, plane.CropWidth).CopyTo(result.AsSpan(y * plane.CropWidth));
        }

        return result;
    }
}
